         // that has not been fully validated yet. The earlier blocks need to be
         // kept to validate the snapshot
-        prune_start = Assert(SnapshotBase())->nHeight + 1;
+        prune_start = Assert(SnapshotBase())->nHeight - 1;
     }

     int max_prune = std::max<int>(
